import re, math
from collections import Counter

def vec(text):
    return Counter(re.findall(r"[a-z0-9£]+", text.lower()))

def cosine(a, b):
    dot = sum(a[w] * b[w] for w in a)
    return dot / (math.sqrt(sum(v * v for v in a.values())) * math.sqrt(sum(v * v for v in b.values())) or 1)

def retrieve(question, k=2):
    q = vec(question)
    ranked = sorted(DOCS, key=lambda d: cosine(q, vec(DOCS[d])), reverse=True)
    return [(d, round(cosine(q, vec(DOCS[d])), 2)) for d in ranked[:k]]

print(retrieve("How many days of leave can I carry over?"))
